import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{r as n,o,c as s,f as h,b as i,d as e,a as t,e as r}from"./app-b08010c0.js";const p={},d=i("h1",{id:"当构建成本为零时-该做什么",tabindex:"-1"},[i("a",{class:"header-anchor",href:"#当构建成本为零时-该做什么","aria-hidden":"true"},"#"),e(" 当构建成本为零时，该做什么?")],-1),c=i("blockquote",null,[i("p",null,"AI 已经让开发成本越来越低，为什么我们还是不知道该做什么？")],-1),u=i("p",null,[i("strong",null,"AI 降低的是构建成本和寻找机会的成本，并没有降低完成商业闭环的成本"),e("。真正应该寻找的不是一个“看起来有护城河的创意”，而是一笔现在就能成交、能够重复，并且会逐渐积累优势的交易。")],-1),_={href:"https://lixiaolai.com/articles/2026-07-31/what-to-build-when-building-is-free",target:"_blank",rel:"noopener noreferrer"},g=r('<h2 id="一、开发便宜了-最后一公里没有" tabindex="-1"><a class="header-anchor" href="#一、开发便宜了-最后一公里没有" aria-hidden="true">#</a> 一、开发便宜了，最后一公里没有</h2><p>AI 可以快速生成代码、内容和方案，但一个真实业务还包括：</p><ul><li>找到客户并取得信任；</li><li>理解没有文档的工作流程；</li><li>接入客户现有系统；</li><li>改变客户的工作习惯；</li><li>处理各种异常情况；</li><li>承担交付责任；</li><li>收款、售后和持续运营。</li></ul><p>这些事情并没有因为 AI 而自动变便宜。</p><p>文章引用 McKinsey 的数据：88% 的受访企业已经在业务中经常使用 AI，但只有39%表示 AI 对企业 EBIT 产生了影响。</p><p>因此，真正的问题不再是：</p><blockquote><p>我能做出什么？</p></blockquote><p>而是：</p><blockquote><p>我能赢下什么交易？反复赢下这种交易以后，我会积累什么？</p></blockquote>',9),f={href:"https://lixiaolai.com/articles/2026-07-31/what-to-build-when-building-is-free#the-reframe-building-got-cheap-the-last-mile-didn-t",target:"_blank",rel:"noopener noreferrer"},b=r('<h2 id="二、先选择自己玩的游戏" tabindex="-1"><a class="header-anchor" href="#二、先选择自己玩的游戏" aria-hidden="true">#</a> 二、先选择自己玩的游戏</h2><p>文章把创业分成三种完全不同的游戏：</p><ol><li><p><strong>现金流生意</strong></p><p>目标是持续、重复地获得付费交易，不一定需要强大的长期护城河。地域、人脉、便利性、客户惰性和优秀运营，都可能让你长期赚钱。</p></li><li><p><strong>长期经营的公司</strong></p><p>重点是：每增加一个客户，是否会积累数据、信任、品牌、集成关系或工作流控制权。</p></li><li><p><strong>VC 规模的公司</strong></p><p>目标是成为某个品类的超级赢家，需要考虑巨大市场、幂律回报和垄断性。</p></li></ol><p>不能拿 VC 的“持久护城河”要求去否定一门不错的现金流生意，也不能拿独立开发者“跟着付费走”的方法去判断一个长期风险投资项目。</p><p>在选择方向前，应该先明确目标收入、首次收入时间、投入资本、最长销售周期、运营复杂度，以及对监管和责任风险的承受能力。</p>',5),m={href:"https://lixiaolai.com/articles/2026-07-31/what-to-build-when-building-is-free#first-decide-which-game-you-re-playing",target:"_blank",rel:"noopener noreferrer"},x=r('<h2 id="三、六个容易误导开发者的创业直觉" tabindex="-1"><a class="header-anchor" href="#三、六个容易误导开发者的创业直觉" aria-hidden="true">#</a> 三、六个容易误导开发者的创业直觉</h2><p>文章反驳了六种听起来很聪明的观点：</p><ol><li><p><strong>“开始之前必须找到护城河”</strong></p><p>早期公司通常没有护城河，只有一个切入口和待验证的假设。更应该问：每增加一位客户，什么东西会变得更强？</p></li><li><p><strong>“按结果收费就一定利润高”</strong></p><p>按结果收费只是把输入质量、返工、人工审核、责任和归因风险转移给了你。只有结果明确、可衡量、可审计并且异常较少时，它才可能高利润。</p></li><li><p><strong>“工具地位弱，必须拥有最终结果”</strong></p><p>真正的区别不是工具与结果，而是你是一个<strong>控制点</strong>，还是一个可以被替换的参与者。记录系统、账本、授权层和审批入口，即使只是工具，也可能占据价值链的核心位置。</p></li><li><p><strong>“拥有受众就等于拥有护城河”</strong></p><p>社交平台上的关注者通常是租来的。真正可靠的是一套可重复的获客流程：触发事件、可接触买家、可信信息、转化、留存和转介绍。</p></li><li><p><strong>“只去资金已经流动的地方”</strong></p><p>现有支出更容易产生现金流，但也容易把产品限制在旧工作流里。新需求风险更高，却可能产生新的品类级公司。</p></li><li><p><strong>“只能从自己已有的优势出发”</strong></p><p>现有优势可以降低探索成本，但不应该成为边界。专业知识、行业关系和客户渠道，都可以通过学习、合作及亲自参与一线工作建立起来。</p></li></ol>',3),k={href:"https://lixiaolai.com/articles/2026-07-31/what-to-build-when-building-is-free#six-instincts-that-feel-smart-and-cost-you-money",target:"_blank",rel:"noopener noreferrer"},w=r('<h2 id="四、作者给出的核心方法-付费切入口锦标赛" tabindex="-1"><a class="header-anchor" href="#四、作者给出的核心方法-付费切入口锦标赛" aria-hidden="true">#</a> 四、作者给出的核心方法：付费切入口锦标赛</h2><p>不要坐在家里比较三个创业想法，而是让三个方向用真实证据竞争你的投入。</p><p>具体方法是：</p><h3 id="_1-找到三个具有-交易形状-的问题" tabindex="-1"><a class="header-anchor" href="#_1-找到三个具有-交易形状-的问题" aria-hidden="true">#</a> 1. 找到三个具有“交易形状”的问题</h3><p>一个好问题应该具备：</p><ul><li>明确的触发事件；</li><li>明确的负责人和付费者；</li><li>可以衡量的完成状态；</li><li>会频繁重复；</li><li>失败会造成实际损失；</li><li>可以获得必要数据；</li><li>错误能够被发现。</li></ul><p>“帮企业改善营销”不是一个好的交易形状。</p><p>“在三分钟内响应每条有效线索，生成合规报价并预约现场检查”才是。</p><h3 id="_2-先卖服务-不要先开发产品" tabindex="-1"><a class="header-anchor" href="#_2-先卖服务-不要先开发产品" aria-hidden="true">#</a> 2. 先卖服务，不要先开发产品</h3><p>针对三个方向，先用“人工＋AI”完成交付。</p><p>只承认真正的需求证据：</p><ul><li>客户付款；</li><li>提供系统访问权限；</li><li>提供真实业务数据；</li><li>作出具有约束力的运营承诺。</li></ul><p>问卷、称赞、候补名单和口头表示感兴趣，都不算强证据。</p><h3 id="_3-记录交付中难看的部分" tabindex="-1"><a class="header-anchor" href="#_3-记录交付中难看的部分" aria-hidden="true">#</a> 3. 记录交付中难看的部分</h3><p>重点记录：</p><ul><li>外联到付费试点的转化率；</li><li>成交需要多长时间；</li><li>扣除人工审核后的真实毛利润；</li><li>每笔交易产生多少异常；</li><li>返工和售后需要多少时间。</li></ul><h3 id="_4-通过四道门筛选" tabindex="-1"><a class="header-anchor" href="#_4-通过四道门筛选" aria-hidden="true">#</a> 4. 通过四道门筛选</h3><ul><li><strong>拉力</strong>：客户是否很快愿意付费？</li><li><strong>经济性</strong>：扣除返工、异常和责任成本后是否赚钱？</li><li><strong>可重复性</strong>：同一报价和渠道能否获得接下来十位客户？</li><li><strong>复利性</strong>：交付是否积累数据、信任、集成、转介绍或控制权？</li></ul><p>最后，<strong>只开发重复交付过程中暴露出的瓶颈，不要一开始做完整产品。</strong></p>',19),I={href:"https://lixiaolai.com/articles/2026-07-31/what-to-build-when-building-is-free#the-method-a-paid-wedge-tournament",target:"_blank",rel:"noopener noreferrer"},A=r('<h2 id="五、最重要的指标-异常经济学" tabindex="-1"><a class="header-anchor" href="#五、最重要的指标-异常经济学" aria-hidden="true">#</a> 五、最重要的指标：异常经济学</h2><p>文章认为，判断 AI 生意能不能成立，最重要的不是模型准确率，而是剩余异常的成本。</p><p>AI 能完成95%的工作，不一定代表产品有价值：</p><ul><li>如果剩余5%很容易发现、处理成本很低，产品可能非常赚钱；</li><li>如果剩余5%悄无声息、后果严重，还需要专家处理，整个模式可能无法成立。</li></ul><p>所以要观察：</p><ul><li>每笔交易的异常数量；</li><li>人工审核时间；</li><li>返工率；</li><li>漏报成本；</li><li>处理异常需要什么级别的人员；</li><li>随着规模增长，异常率是否下降。</li></ul><p>如果业务增长了，人工处理和异常成本却没有下降，那么所谓的“AI 软件公司”，可能只是一家成本结构更差的人力服务公司。</p>',7),y={href:"https://lixiaolai.com/articles/2026-07-31/what-to-build-when-building-is-free#the-kill-metric-exception-economics",target:"_blank",rel:"noopener noreferrer"},B=r('<h2 id="六、作者最后给出的行动方案" tabindex="-1"><a class="header-anchor" href="#六、作者最后给出的行动方案" aria-hidden="true">#</a> 六、作者最后给出的行动方案</h2><p>文章建议你下周就做五件事：</p><ol><li>写清楚自己玩的是现金流、长期经营还是 VC 游戏；</li><li>列出三个你能接触到买家的“交易形状”问题；</li><li>为最强的方向设计一个人工交付的付费服务；</li><li>向真实客户索要付款、数据或系统访问权限；</li><li>亲自完成交付，记录异常，只开发反复出现的瓶颈。</li></ol><h2 id="一句话总结" tabindex="-1"><a class="header-anchor" href="#一句话总结" aria-hidden="true">#</a> 一句话总结</h2><blockquote><p>AI 没有替你回答“应该开发什么”，而是大幅降低了寻找答案的成本。不要继续空想创意和护城河，用三个可证伪的付费实验寻找真实需求，再把交付过程中最影响效率、利润和规模化的环节做成产品。</p></blockquote><p>我认为文章最有价值的地方，是把产品开发顺序倒了过来：</p><p><strong>不是“发现创意→开发产品→寻找客户”，而是“找到交易→人工交付→测量异常→开发瓶颈→逐渐产品化”。</strong></p>',7);function V(q,C){const l=n("ExternalLinkIcon");return o(),s("div",null,[d,h("- more -"),c,u,i("p",null,[i("a",_,[e("阅读原文"),t(l)])]),g,i("p",null,[i("a",f,[e("对应章节：Building got cheap, the last mile didn’t"),t(l)])]),b,i("p",null,[i("a",m,[e("对应章节：Decide which game you’re playing"),t(l)])]),x,i("p",null,[i("a",k,[e("对应章节：Six instincts that feel smart and cost you money"),t(l)])]),w,i("p",null,[i("a",I,[e("对应章节：Paid-wedge tournament"),t(l)])]),A,i("p",null,[i("a",y,[e("对应章节：Exception economics"),t(l)])]),B])}const W=a(p,[["render",V],["__file","What-to-Build-When-Building-Is-Free.html.vue"]]);export{W as default};
